#!/usr/bin/env bash
set -euo pipefail

repo_root="${1:-.}"
temp_script="$(mktemp)"
trap 'rm -f "$temp_script"' EXIT

base64 --decode > "$temp_script" <<'PHASE8_PY'

PHASE8_PY

python "$temp_script" "$repo_root"

echo
echo "Format and validate Phase 8:"
echo "  npm run format"
echo "  npm test -- app/game/survival/night-rest-coverage.test.ts"
echo "  npm test -- app/game/survival/night-rest-lifecycle.integration.test.ts"
echo "  npm test -- app/game/events/catalogue/night-catalogue.test.ts"
echo "  npm test -- app/game/simulation/balance-report.test.ts"
echo "  npm test -- app/game/engine/simulation-stress.test.ts"
echo "  npm run typecheck"
echo "  npm run lint"
echo "  npm test"
echo "  npm run test:e2e"
echo "  npm run build"
echo "  npm run balance:report"
echo
echo "Review the Phase 8 diff:"
echo "  git diff -- app/game/engine/event-sequencer.ts app/game/engine/simulation-stress.test.ts app/game/events/validation/validate-event-resolution.ts app/game/survival app/game/simulation"